{
  "titre": "Réviser les Trente Glorieuses",
  "objectifGeneral": "Se remémorer les enjeux, les transformations et les limites de la période des Trente Glorieuses en mobilisant les notions clés.",
  "notionsPivots": [
    "l'économie d'endettement",
    "le baby-boom",
    "la société de consommation",
    "l'État-providence",
    "la désindustrialisation",
    "les chocs pétroliers"
  ],
  "etapes": [
    {
      "titre": "Autodiagnostic initial",
      "objectif": "Identifier ses acquis et ses lacunes sur les notions des Trente Glorieuses",
      "cartes": [
        {
          "titre": "Quiz de départ",
          "objectif": "Évaluer ses connaissances initiales",
          "module": "QuizSetQCM",
          "palier": "decouverte",
          "duree": 10,
          "consigne": "Répondre à 10 questions à choix multiples sur les principales caractéristiques des Trente Glorieuses en cochant la ou les bonnes réponses. Ce quiz ne sera pas noté mais servira de point de départ pour votre révision."
        }
      ]
    },
    {
      "titre": "Comprendre les mécanismes",
      "objectif": "Assimiler les causes, manifestations et conséquences des transformations économiques et sociales",
      "cartes": [
        {
          "titre": "Frise chronologique",
          "objectif": "Repérer les dates et événements marquants",
          "module": "Timeline",
          "palier": "entrainement",
          "duree": 15,
          "consigne": "Placer sur une frise interactive les événements et dates clés des Trente Glorieuses parmi ceux proposés : 1945, 1949, 1958, 1960, 1973, 1974, 1979, plan Marshall, Trente Glorieuses, baby-boom."
        },
        {
          "titre": "Carte à mémoriser",
          "objectif": "Maîtriser les définitions des termes essentiels",
          "module": "Flashcards",
          "palier": "entrainement",
          "duree": 10,
          "consigne": "Étudier un jeu de 12 flashcards présentant les notions pivot du chapitre (économie d'endettement, baby-boom, etc.) en utilisant la fonction de découverte/masquage pour s'auto-évaluer."
        }
      ]
    },
    {
      "titre": "Analyser les transformations",
      "objectif": "Comprendre les impacts économiques et sociaux des Trente Glorieuses",
      "cartes": [
        {
          "titre": "Étude de cas",
          "objectif": "Interpréter des documents pour expliquer une évolution",
          "module": "DragTheWords",
          "palier": "transfert",
          "duree": 15,
          "consigne": "Compléter un texte lacunaire de 10 lignes en glissant les mots manquants parmi une liste proposée, en justifiant à l'écrit si nécessaire les choix des termes (utiliser les notions pivots)."
        },
        {
          "titre": "Quiz d'application",
          "objectif": "Valider sa compréhension des concepts clés",
          "module": "QuizSetVF",
          "palier": "transfert",
          "duree": 10,
          "consigne": "Répondre à un quiz de 8 questions vrai/faux sur les transformations sociales et économiques, avec retour immédiat à chaque réponse (explication courte + correction)."
        }
      ]
    }
  ]
}

